import { cn } from "@/lib/utils"

/**
 * Marks anything the AI wrote. Five dots; the centre one is the signal colour.
 * `thinking`: the dots pulse in turn while the AI is reading sources.
 */
export interface AiSparkProps {
  thinking?: boolean
  className?: string
}

const DOTS: [number, number][] = [[7, 2.3], [11.7, 7], [7, 11.7], [2.3, 7]]

export function AiSpark({ thinking = false, className }: AiSparkProps) {
  return (
    <svg data-slot="ai-spark" viewBox="0 0 14 14" aria-hidden="true" className={cn("size-3.5 shrink-0", className)}>
      {DOTS.map(([cx, cy], i) => (
        <circle
          key={i}
          cx={cx}
          cy={cy}
          r={1.5}
          className={cn("fill-foreground", thinking && "animate-pulse motion-reduce:animate-none")}
          style={thinking ? { animationDelay: `${i * 150}ms` } : undefined}
        />
      ))}
      <circle cx={7} cy={7} r={1.5} className="fill-signal" />
    </svg>
  )
}
